SELECT ~ DATE'2024-01-01';

-- @sweep ~ slot=0 type=date form=column
SELECT ~ x FROM VALUES (DATE'2024-01-01'), (0), (NULL), (DATE'2024-01-01') AS t(x);

-- @sweep ~ slot=0 type=timestamp
SELECT ~ TIMESTAMP'2024-01-01 10:00:00';

-- @sweep ~ slot=0 type=timestamp_ntz
SELECT ~ TIMESTAMP_NTZ'2024-01-01 10:00:00';

-- @sweep ~ slot=0 type=interval_dt
SELECT ~ INTERVAL '1' DAY;

-- @sweep ~ slot=0 type=interval_ym
SELECT ~ INTERVAL '1' MONTH;

-- @sweep ~ slot=0 type=array_int
SELECT ~ array(1, 2);

-- @sweep ~ slot=0 type=array_int form=column
SELECT ~ x FROM VALUES (array(1, 2)), (0), (NULL), (array(1, 2)) AS t(x);

-- @sweep ~ slot=0 type=array_str
SELECT ~ array('a');

-- @sweep ~ slot=0 type=map
SELECT ~ map('a', 1);

-- @sweep ~ slot=0 type=struct
SELECT ~ named_struct('a', 1);
